export function MainElement({
  heading = "{{heading}}",
  body = "{{body}}",
  accent = "{{accent}}",
  showChrome = {{showChrome}},
}) {
  const chrome = { background: "#24143012", color: "#24143070", fontSize: 11, textTransform: "uppercase", letterSpacing: "0.06em", textAlign: "center", padding: 8 };
  return (
    <div style={{ width: 340, boxSizing: "border-box", font: "14px/1.5 system-ui, sans-serif" }}>
      {showChrome && <div style={{ ...chrome, borderRadius: "10px 10px 0 0" }}>header</div>}
      <main style={{ background: "#FAF7F2", borderLeft: `4px solid ${accent}`, padding: "20px 22px" }}>
        <p style={{ margin: "0 0 8px", font: "700 11px ui-monospace, monospace", color: accent }}>&lt;main&gt;</p>
        <h2 style={{ margin: "0 0 8px", fontSize: 20, fontWeight: 700, color: "#241430" }}>{heading}</h2>
        <p style={{ margin: 0, color: "#241430cc" }}>{body}</p>
      </main>
      {showChrome && <div style={{ ...chrome, borderRadius: "0 0 10px 10px" }}>footer</div>}
    </div>
  );
}
